/**
 * One transcript segment, as posted to the server. Wire form is camelCase; `likely_echo` and
 * `utterance_seq` are local-only (never serialized).
 */
public struct SegmentRecord {
    /**
     * uuid v7, assigned once when the segment is created: retries are idempotent.
     */
    public var clientSegmentId: String
    public var channel: Channel
    public var text: String
    public var language: String
    /**
     * Offset from session start, milliseconds.
     */
    public var startMs: UInt64
    public var endMs: UInt64
    public var confidence: Float?
    public var isFinal: Bool
    /**
     * `me` utterance judged to be speaker bleed of `others` (echo guard). Local only.
     */
    public var likelyEcho: Bool
    /**
     * Per-channel utterance counter (from 0). Local only.
     */
    public var utteranceSeq: UInt64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * uuid v7, assigned once when the segment is created: retries are idempotent.
         */clientSegmentId: String, channel: Channel, text: String, language: String, 
        /**
         * Offset from session start, milliseconds.
         */startMs: UInt64, endMs: UInt64, confidence: Float?, isFinal: Bool, 
        /**
         * `me` utterance judged to be speaker bleed of `others` (echo guard). Local only.
         */likelyEcho: Bool, 
        /**
         * Per-channel utterance counter (from 0). Local only.
         */utteranceSeq: UInt64) {
        self.clientSegmentId = clientSegmentId
        self.channel = channel
        self.text = text
        self.language = language
        self.startMs = startMs
        self.endMs = endMs
        self.confidence = confidence
        self.isFinal = isFinal
        self.likelyEcho = likelyEcho
        self.utteranceSeq = utteranceSeq
    }
}

