extension StartParams: Equatable, Hashable {
    public static func ==(lhs: StartParams, rhs: StartParams) -> Bool {
        if lhs.baseUrl != rhs.baseUrl {
            return false
        }
        if lhs.sessionId != rhs.sessionId {
            return false
        }
        if lhs.bearer != rhs.bearer {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(baseUrl)
        hasher.combine(sessionId)
        hasher.combine(bearer)
    }
}



