// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Events for the overlay / UI.
 */

public enum CopilotEvent {
    
    /**
     * Accumulated text of the utterance in progress (empty text = cleared).
     */
    case partial(channel: Channel, text: String
    )
    /**
     * A transcript segment (early sentences arrive before the utterance is complete).
     */
    case segment(segment: SegmentRecord
    )
    case status(channel: Channel?, kind: StatusKind, detail: String?
    )
    case error(channel: Channel?, code: String, message: String
    )
    /**
     * Throttled input level (RMS of the audio since the previous `Levels` of the channel).
     */
    case levels(channel: Channel, rms: Float
    )
}


#if compiler(>=6)
extension CopilotEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCopilotEvent: FfiConverterRustBuffer {
    typealias SwiftType = CopilotEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CopilotEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .partial(channel: try FfiConverterTypeChannel.read(from: &buf), text: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .segment(segment: try FfiConverterTypeSegmentRecord.read(from: &buf)
        )
        
        case 3: return .status(channel: try FfiConverterOptionTypeChannel.read(from: &buf), kind: try FfiConverterTypeStatusKind.read(from: &buf), detail: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 4: return .error(channel: try FfiConverterOptionTypeChannel.read(from: &buf), code: try FfiConverterString.read(from: &buf), message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .levels(channel: try FfiConverterTypeChannel.read(from: &buf), rms: try FfiConverterFloat.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CopilotEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .partial(channel,text):
            writeInt(&buf, Int32(1))
            FfiConverterTypeChannel.write(channel, into: &buf)
            FfiConverterString.write(text, into: &buf)
            
        
        case let .segment(segment):
            writeInt(&buf, Int32(2))
            FfiConverterTypeSegmentRecord.write(segment, into: &buf)
            
        
        case let .status(channel,kind,detail):
            writeInt(&buf, Int32(3))
            FfiConverterOptionTypeChannel.write(channel, into: &buf)
            FfiConverterTypeStatusKind.write(kind, into: &buf)
            FfiConverterOptionString.write(detail, into: &buf)
            
        
        case let .error(channel,code,message):
            writeInt(&buf, Int32(4))
            FfiConverterOptionTypeChannel.write(channel, into: &buf)
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .levels(channel,rms):
            writeInt(&buf, Int32(5))
            FfiConverterTypeChannel.write(channel, into: &buf)
            FfiConverterFloat.write(rms, into: &buf)
            
        }
    }
}


